from pathlib import Path
import json,statistics
W=Path(__file__).parent
NAMES=['lines','lazy-sort','ordered-code','packed-sort','code-ranges','html-ranges','all-ranges','lines+all-ranges']
FINAL='production'
lines=['# Measured optimization results','','Generated by `make-results.py`. Negative changes mean less elapsed time. Screening is exploratory; confirmation is independent and uses longer windows. No time is estimated for an excluded comparison.','','## Independent screens','','Each variant uses five alternating 30 ms windows per implementation/input, after 60 ms warmup. The median below describes the 69 selected cases, not a weighted application workload.','','| Variant | Median change across cases | Exact-output guards |','| --- | ---: | ---: |']
for name in NAMES:
 rows=json.loads((W/name/'summary.json').read_text());v=json.loads((W/name/'verification.json').read_text());assert not v['failed'];lines.append(f"| {name} | {statistics.median(r['change_pct'] for r in rows):+.1f}% | {v['count']} / {v['count']} |")
lines+=['','## Repeated confirmation','','The formatted production source scans line ends with memchr and coalesces contiguous code/HTML ranges after the existing table-cell shortcut. Three fresh process pairs, nine alternating 75 ms windows per implementation/input in each pair, after 60 ms warmup. Every process starts from the same frozen cases and options. Latencies summarize the three run medians; the change column retains each paired run separately.','','| Input | Baseline µs | Candidate µs | Paired changes |','| --- | ---: | ---: | --- |']
runs=[json.loads((W/FINAL/f'confirm-{i}/summary.json').read_text()) for i in range(1,4)]
for group in zip(*runs):
 assert len({r['case'] for r in group})==1
 a=statistics.median(r['baseline_ns'] for r in group);b=statistics.median(r['candidate_ns'] for r in group)
 lines.append(f"| {group[0]['case']} | {a/1000:.3f} | {b/1000:.3f} | "+', '.join(f"{r['change_pct']:+.1f}%" for r in group)+' |')
if (W/'corpus/final-1-summary.json').exists():
 lines+=['','## Fresh comparison with Ox Content on its corpus','','Both engines create and destroy fresh parser state, a growing arena where applicable, and owned HTML. Heading IDs are enabled. This uses Ox revision `026d1859d1c35e5fb1ea65e7e855b428a918b9bb`, separate from the fixed native publication adapter revision. Three process groups, nine 60 ms windows per engine/input; see the previous profiling report for normalization and syntax boundaries. Concatenations with unequal output are diagnostics and do not support a speed ranking. The primary Ox comparison uses its growing arena.','','| Document | Equal normalized output | Ferromark µs | Ox growing µs | F / Ox |','| --- | --- | ---: | ---: | ---: |']
 runs=[json.loads((W/f'corpus/final-{i}-summary.json').read_text()) for i in range(1,4)]
 for group in zip(*runs):
  a=statistics.median(r['median_ns']['ferro'] for r in group);b=statistics.median(r['median_ns']['ox-grow'] for r in group);r=group[0]
  lines.append(f"| {r['case']} | {'yes' if r['equal'] else 'no; diagnostic'} | {a/1000:.2f} | {b/1000:.2f} | {a/b:.2f}× |")
if (W/'memory/summary.json').exists():
 lines+=['','## Allocation cross-check','','Requested live heap bytes measured with the same allocation counter as the previous memory report. These are allocator requests, not RSS or a universal memory bound. Full samples cover 45 inputs and three processes with ten identical observations each. Inputs and normalization remain unchanged.','','| Input | Input bytes | Previous F peak | New F peak | Ox growing peak |','| --- | ---: | ---: | ---: | ---: |']
 old={r['case']:r for r in json.loads((W/'memory/baseline-summary.json').read_text())}
 for r in json.loads((W/'memory/summary.json').read_text()):
  if r['input_bytes']>=250000:
   lines.append(f"| {r['case']} | {r['input_bytes']} | {old[r['case']]['ferro']['peak_live_bytes']} | {r['ferro']['peak_live_bytes']} | {r['ox-grow']['peak_live_bytes']} |")
(W/'RESULTS.md').write_text('\n'.join(lines)+'\n')
